Just bumped to a different use case that needs to detect whether knit<br>is running or not, e.g.<br><br>&gt; BiocStyle::latex<br>function (..., width = 90, short.fignames = FALSE, fig.path,<br>    error = FALSE, use.unsrturl = TRUE)<br>{<br>    options(..., width = width)<br>    cat(sprintf(&quot;\RequirePackage{%s}

&quot;, sub(&quot;.sty$&quot;, &quot;&quot;,<br>        .bioconductor.sty)))<br>    if (use.unsrturl) {<br>        bst &lt;- file.path(system.file(package = &quot;BiocStyle&quot;, &quot;resources&quot;,<br>            &quot;latex&quot;), &quot;unsrturl&quot;)<br>        cat(sprintf(&quot;\AtBeginDocument{\bibliographystyle{%s}}
&quot;,<br>            bst))<br>    }<br>    setPrefix = function(x) {<br>        cat(sprintf(&quot;\renewcommand{\prefix}[1]{%s#1}&quot;, x))<br>    }<br>    fs = sapply(sys.calls(), function(x) as.character(x)[1])<br>    id = pmatch(&quot;knit&quot;, fs, nomatch = 0)<br>    if (id &gt; 0 &amp;&amp; exists(&quot;opts_chunk&quot;)) {<br>        if (missing(fig.path)) {<br>            fig.path = knitr::opts_chunk$get(&quot;fig.path&quot;, default = TRUE)<br>        }<br>        if (isTRUE(short.fignames))<br>            setPrefix(fig.path)<br>        knitr::opts_knit$set(latex.options.color = &quot;usenames,dvipsnames&quot;)<br>        knitr::opts_chunk$set(fig.path = fig.path, error = error)<br>    }<br>    else {<br>        if (isTRUE(short.fignames))<br>            setPrefix(&quot;\jobname-&quot;)<br>    }<br>}<br>&lt;environment: namespace:BiocStyle&gt;<br><br>Quite a hack that would be better done with a knitr::is_knitting() function.<br><br>/Henrik<br>
